import{_ as o,o as u,c as q,ag as p}from"./chunks/framework.CukOUUOK.js";const d=JSON.parse('{"title":"以人民的名义：一场归还权力的革命如何吞并了社会","description":"一、一个被篡改的起点 1871年，巴黎工人阶级在武装起义中建立了人类历史上第一个无产阶级政权——巴黎公社。仅仅72天后，公社就被凡尔赛政府血腥镇压。但马克思在公社覆灭后第三天写就的《法兰西内战》中，却…","frontmatter":{"title":"以人民的名义：一场归还权力的革命如何吞并了社会","categories":"权力与制度","tags":["政治思想史","历史","制度"],"description":"一、一个被篡改的起点 1871年，巴黎工人阶级在武装起义中建立了人类历史上第一个无产阶级政权——巴黎公社。仅仅72天后，公社就被凡尔赛政府血腥镇压。但马克思在公社覆灭后第三天写就的《法兰西内战》中，却…","date":"2026-09-05T12:00:00.000Z"},"headers":[],"relativePath":"posts/2026-09-05-in-the-name-of-the-people.md","filePath":"posts/2026-09-05-in-the-name-of-the-people.md","lastUpdated":1789992750000}'),a={name:"posts/2026-09-05-in-the-name-of-the-people.md"};function e(r,t,l,i,n,s){return u(),q("div",null,[...t[0]||(t[0]=[p('<h1 id="以人民的名义-一场归还权力的革命如何吞并了社会" tabindex="-1">以人民的名义：一场归还权力的革命如何吞并了社会 <a class="header-anchor" href="#以人民的名义-一场归还权力的革命如何吞并了社会" aria-label="Permalink to &quot;以人民的名义：一场归还权力的革命如何吞并了社会&quot;">​</a></h1><h3 id="一、一个被篡改的起点" tabindex="-1">一、一个被篡改的起点 <a class="header-anchor" href="#一、一个被篡改的起点" aria-label="Permalink to &quot;一、一个被篡改的起点&quot;">​</a></h3><p>1871年，巴黎工人阶级在武装起义中建立了人类历史上第一个无产阶级政权——巴黎公社。仅仅72天后，公社就被凡尔赛政府血腥镇压。但马克思在公社覆灭后第三天写就的《法兰西内战》中，却称它是&quot;终于发现的可以使劳动在经济上获得解放的政治形式&quot;，是&quot;社会把国家政权重新收回&quot;的运动。</p><p>马克思从公社的实践中提炼出的核心原则，构成了马克思主义关于&quot;无产阶级专政&quot;最原初、最具体的设计：</p><ul><li>所有公职人员由普选产生，随时可以罢免，权力始终牢牢掌握在选民手中；</li><li>所有公职人员只领取相当于熟练工人的工资，取消一切特权和公务津贴，从根本上铲除官僚特权阶层产生的土壤；</li><li>废除常备军和独立警察，代之以武装工人的民兵组织；</li><li>实行议行合一的公社委员会制度，立法和行政不分立，代表必须亲自工作、亲自执行法律、亲自对选民负责；</li><li>实行彻底的地方自治，巴黎公社只是法国所有村镇自治联合体的一个组成部分，中央只保留极少数必要职能。</li></ul><p>马克思明确指出：公社的存在不是为了把国家政权从一个阶级手里转到另一个阶级手里，而是为了&quot;把国家这个统治机关从凌驾于社会之上的东西变成完全服从社会的东西&quot;。无产阶级专政不是一个永久性的权力形态，而是一个过渡性的、自我消解的阶段：它的历史使命不是强化国家权力，而是把被国家篡夺的社会权力全部归还给社会，最终实现国家的消亡，建立&quot;自由人的联合体&quot;。</p><p>列宁在《国家与革命》中将这些原则系统化为防止官僚主义的完整方案：&quot;不但实行选举制度，而且随时可以撤换；薪金不得高于工人的工资；立刻转到使所有的人都来执行监督和监察的职能，使所有的人暂时都变成&#39;官僚&#39;，因而使任何人都不能成为&#39;官僚&#39;。&quot;他甚至断言：&quot;在社会主义下，所有的人将轮流来管理，因此很快就会习惯于不要任何人来管理。&quot;</p><p>这就是马克思主义关于&quot;无产阶级专政&quot;的原初定义：它不是国家权力的强化，而是国家权力的自我消解；不是少数人代表人民行使权力，而是人民自己行使权力；不是用国家取代社会，而是让社会收回国家。</p><p>但20世纪所有以马克思主义为旗帜的革命，最终都走向了它的反面：不是社会收回了国家权力，而是国家彻底吞并了社会；不是公职人员随时可罢免的公仆，而是享有特殊待遇的官僚特权阶层；不是地方自治的联合体，而是高度集权的单一制国家；不是所有人的轮流管理，而是少数人对多数人的永久统治。</p><p>这不是&quot;执行偏差&quot;，而是从理论源头就埋下的结构性异化。</p><h3 id="二、第一次置换-从-群众自治-到-先锋队代表" tabindex="-1">二、第一次置换：从&quot;群众自治&quot;到&quot;先锋队代表&quot; <a class="header-anchor" href="#二、第一次置换-从-群众自治-到-先锋队代表" aria-label="Permalink to &quot;二、第一次置换：从&quot;群众自治&quot;到&quot;先锋队代表&quot;&quot;">​</a></h3><p>异化的第一步，发生在列宁对马克思主义的改造中。</p><p>马克思设想的无产阶级专政，主体是组织在公社里的全体劳动者，权力的运行方式是直接的、自下而上的民主。但列宁在《怎么办？》中提出了&quot;先锋队理论&quot;：工人阶级单靠自己只能形成工联主义意识，社会主义意识必须由职业革命家组成的先锋队从外部灌输进去。因此，无产阶级的权力不能由工人阶级直接行使，而必须由代表工人阶级利益的先锋队——共产党——代为行使。</p><p>这里发生了第一次关键的置换：权力的主体从&quot;组织起来的劳动者&quot;变成了&quot;代表劳动者的先锋队&quot;。</p><p>这个置换在革命夺权阶段有其历史合理性：在沙皇专制的高压下，分散的工人确实无法自发形成统一的革命力量，需要一个高度组织化、纪律化的先锋队来领导。但当革命胜利、政权建立之后，这个&quot;代为行使&quot;的临时安排被永久化了。先锋队不再是一个&quot;代表&quot;，而变成了一个&quot;替代&quot;：不是&quot;替人民行使权力&quot;，而是&quot;代替人民行使权力&quot;。</p><p>罗莎·卢森堡在1918年就敏锐地指出了这个危险：她警告说，如果无产阶级专政只是少数政治家的专政，那它就只是&quot;一种特权阶层对群众的专政&quot;，而不是无产阶级自己的专政。她强调：&quot;无产阶级专政必须是阶级的事业，而不是极少数政治家以阶级的名义实行的事业……公共机构的生活、最广泛的民主、公众的积极参与、不受限制的自由和公开性，这些都是无产阶级专政的本质要求。&quot;</p><p>但列宁和布尔什维克没有接受这个警告。在俄国内战和外国武装干涉的压力下，苏维埃政权迅速走向了集权：1918年解散了立宪会议，1921年禁止了党内派别活动，工会被纳入国家机器，苏维埃从权力机关变成了 rubber stamp。到斯大林时期，这个异化过程彻底完成：党取代了苏维埃，政治局取代了党，总书记取代了政治局，最终一个人的意志取代了所有人的意志。</p><h3 id="三、第二次置换-从-代表人民-到-以人民的名义" tabindex="-1">三、第二次置换：从&quot;代表人民&quot;到&quot;以人民的名义&quot; <a class="header-anchor" href="#三、第二次置换-从-代表人民-到-以人民的名义" aria-label="Permalink to &quot;三、第二次置换：从&quot;代表人民&quot;到&quot;以人民的名义&quot;&quot;">​</a></h3><p>毛泽东领导的中国共产党革命，继承了列宁主义的先锋队框架，但在这个框架的基础上，把异化推向了更彻底的境地。</p><p><strong>第一个维度：单位制——把国家权力渗透到每一个毛细血管</strong></p><p>新中国成立后，中国建立了一套以单位制和人民公社为核心的社会管控体系。在城市，单位不仅是工作场所，还是住房、医疗、教育、养老、甚至婚姻审批的唯一提供者。你的身份、你的福利、你的社会关系、你的生存空间，全部绑定在你所在的单位上。离开单位，你什么都不是。在农村，人民公社把土地、农具、劳动时间、甚至口粮分配全部收归集体，农民被牢牢绑定在土地上，没有任何流动的自由。</p><p>社会学家李路路、李汉林的研究指出：单位制的基本特征是&quot;国家—单位—社会成员&quot;的双重控制与双重依附链条。所有基层单位都表现为国家行政组织的延伸，整个社会的运转依靠自上而下的行政权力。单位制在客观上导致了社会成员的原子化，导致了社会自主性的完全丧失，甚至可以说社会被国家同构。</p><p>这就是托克维尔在《旧制度与大革命》中警告的&quot;中间力量被摧毁&quot;的极致版本：不是&quot;没有中间组织&quot;，而是所有中间组织都被国家化了。工会不是工人与管理者之间的谈判代表，而是&quot;党联系群众的桥梁&quot;——从上到下的传达管道，不是从下到上的利益聚合机制。共青团不是青年的自治组织，而是党的后备军。妇联不是妇女的权益代表，而是党的妇女工作部门。</p><p>社会没有任何独立于国家的&quot;外部&quot;。你不需要&quot;被压制&quot;，因为你已经没有独立于组织的生存空间。</p><p><strong>第二个维度：群众运动——被动员的&quot;参与&quot;如何摧毁真正的自组织能力</strong></p><p>毛时代最独特的政治现象是频繁的群众运动：从土地改革到三反五反，从反右到文化大革命，几乎每隔几年就有一次大规模的群众动员。表面上看，这是&quot;群众参与政治&quot;的最高形式，是&quot;人民当家作主&quot;的体现。</p><p>但这种&quot;参与&quot;和真正的公共讨论有一个根本区别：它是被动员的，不是自发的。</p><p>真正的公共讨论：人们从自己的利益、判断、价值观出发，自发形成意见，然后通过辩论、协商、妥协形成共识或分歧。</p><p>群众运动：中央发出号召→各级组织传达→群众&quot;响应&quot;号召→表达已经被预设好的立场。</p><p>这个区别不是后人的分析，而是毛时代自身的制度实践反复证明的。</p><p>1957年，&quot;百花齐放、百家争鸣&quot;的号召发出后，知识分子真诚地提出了批评意见。但毛泽东在《事情正在起变化》中明确将这一过程定性为&quot;引蛇出洞&quot;——号召本身就是策略设计的一部分，目的是让&quot;右派&quot;暴露出来以便打击。群众&quot;响应&quot;号召说出的话，不是他们自己的判断，而是被预设的剧本中的一句台词；当剧本翻页，台词就变了。</p><p>文化大革命期间，中央文革小组对群众组织进行了严格的分类定性：哪些是&quot;革命左派&quot;，哪些是&quot;保守派&quot;，哪些是&quot;反动组织&quot;，全部由上面裁定。群众可以&quot;造反&quot;，但只能造被允许造的反；可以&quot;串联&quot;，但只能按照指定的方向串联。任何超出预设边界的自发联合，立刻被定性为&quot;反革命小集团&quot;予以取缔。</p><p>1976年的四五运动更为典型：群众自发悼念周恩来、批评&quot;四人帮&quot;，这是真正的、未经动员的公共表达。但官方通报将其定性为&quot;反革命事件&quot;，参与者遭到逮捕和追查。这个事件传递的信号极其清晰：你可以&quot;响应&quot;号召，但不能&quot;自发&quot;行动；你可以说上面允许你说的话，但不能说你真正想说的话。</p><p>所有的群众运动都是自上而下发起的，运动的对象、节奏、边界、甚至&quot;正确&quot;的表态方式，全部由上级预先设定。群众只需要&quot;响应&quot;，不需要&quot;思考&quot;；只需要&quot;站队&quot;，不需要&quot;辩论&quot;。</p><p>这种&quot;响应式参与&quot;有一个致命的副作用：它摧毁了社会自下而上组织的能力，同时制造了&quot;我在参与&quot;的幻觉。人们以为自己&quot;当家作主&quot;了，但实际上他们只是在执行上面布置的任务。当运动的方向发生变化时（比如从&quot;批斗走资派&quot;突然变成&quot;平反&quot;），群众只能跟着转向，没有任何自主判断的空间。</p><p>这就是一个自我强化的闭环：管控→群众丧失自发组织能力→管控者说&quot;看，他们果然不会自己组织，必须继续由我们来领导&quot;→更多管控→群众进一步丧失能力→……</p><p><strong>第三个维度：个人崇拜——一个自我封闭的认知闭环</strong></p><p>毛时代最显著的政治现象是对毛泽东的个人崇拜。这种崇拜不是简单的&quot;迷信&quot;，而是一个系统性的认知闭环的终极形式。</p><p>当&quot;无产阶级专政&quot;被等同于&quot;党的专政&quot;，&quot;党的专政&quot;被等同于&quot;领袖的意志&quot;时，整个系统的正当性就系于一个人。这时候，对领袖的质疑就不再是&quot;政策批评&quot;，而是&quot;反革命&quot;——因为它威胁到了整个权力结构的根基。</p><p>个人崇拜的结构性功能是：把所有制度失败的责任，转化为对领袖忠诚度的测试。</p><ul><li>大跃进导致大饥荒？不是路线问题，是下面执行不力，或者阶级敌人在破坏；</li><li>经济困难？不是政策错误，是自然灾害或苏联撤走专家；</li><li>社会动荡？不是管控过度，是&quot;阶级斗争还在继续&quot;。</li></ul><p>这个机制的恶毒之处在于：它让系统无法从错误中学习。因为承认错误等于承认领袖不是永远正确，而承认领袖不是永远正确等于动摇整个系统的正当性。</p><p>这里面包含着一个深刻的因果倒置：革命宣称要&quot;归还权力给人民&quot;→但说&quot;人民暂时还没能力&quot;→所以需要先由先锋队代为行使→在代为行使的过程中，人民的自治能力进一步退化→先锋队说&quot;看，他们果然还不行&quot;→继续代为行使→……</p><p>腿早就断了，&quot;放开&quot;只是让那个人试图站起来。</p><h3 id="四、被篡改的遗产-政治文化的深层结构" tabindex="-1">四、被篡改的遗产：政治文化的深层结构 <a class="header-anchor" href="#四、被篡改的遗产-政治文化的深层结构" aria-label="Permalink to &quot;四、被篡改的遗产：政治文化的深层结构&quot;">​</a></h3><p>毛时代留下的最深层的遗产，不是计划经济，不是单位制（这些都在改革开放后松动了），而是政治文化的深层结构：</p><ul><li><strong>&quot;人民&quot;被习惯性地理解为&quot;被代表的&quot;</strong>，而不是&quot;自己行动的&quot;。即使今天，大多数人谈到&quot;人民&quot;时，想的是一个抽象的、被动的整体，而不是具体的、能动的个体集合。</li><li><strong>国家权力被习惯性地理解为&quot;解决问题的唯一主体&quot;</strong>。遇到问题，人们的第一反应是&quot;政府应该管&quot;，而不是&quot;我们自己能不能组织起来解决&quot;。这不是因为人们&quot;天生依赖政府&quot;，而是因为七十年来，国家系统性地摧毁了所有替代性的组织能力。</li><li><strong>&quot;稳定&quot;被习惯性地理解为&quot;没有公开冲突&quot;</strong>，而不是&quot;冲突被制度化地处理&quot;。这个理解深深植根于毛时代的&quot;阶级斗争&quot;叙事——冲突不是你死我活，就是被压制。没有&quot;在规则内竞争&quot;的中间状态。</li><li><strong>领袖被习惯性地理解为&quot;最终裁决者&quot;</strong>，而不是&quot;众多权力中心之一&quot;。即使在今天，人们谈到政治时，仍然习惯性地聚焦于&quot;上面怎么想&quot;，而不是&quot;我们怎么组织&quot;。</li></ul><p>这些深层结构，就是托克维尔说的&quot;民情&quot;——不是法律，不是制度，而是一个社会习以为常的思维方式、情感结构、行为模式。</p><p>制度可以在几年内改变，但民情需要几代人才能改变。</p><p>这就是为什么这种&quot;能力退化&quot;如此难以修复——因为它不是&quot;人们忘记了怎么做&quot;，而是<strong>人们从未学过怎么做</strong>。他们的父母没学过，他们的祖父母没学过，他们的曾祖父母不仅没学过，还被系统性地惩罚过试图学习的人。</p><h3 id="五、当代回响-死亡螺旋的延续" tabindex="-1">五、当代回响：死亡螺旋的延续 <a class="header-anchor" href="#五、当代回响-死亡螺旋的延续" aria-label="Permalink to &quot;五、当代回响：死亡螺旋的延续&quot;">​</a></h3><p>今天中国社会中广泛存在的&quot;原子化&quot;、公共讨论能力的退化、以及用&quot;素质论&quot;来论证管控合理性的思维方式，都不是凭空出现的。它们是毛时代留下的政治遗产在改革开放后的延续和变形。</p><p>改革开放解决了经济问题，但没有解决政治文化问题。市场创造了新的利益集团，但没有创造新的政治主体。互联网创造了新的连接方式，但没有创造新的组织能力。</p><p>当我们听到有人说&quot;中国人民素质低，搞不了民主&quot;时，必须清醒地认识到：这个判断本身就是因果倒置的产物。不是人民天生不具备自治能力，而是七十年来系统性地剥夺了人民练习自治的机会，然后用这种剥夺的结果来论证继续剥夺的合理性。</p><p>巴黎公社的原则告诉我们：社会主义的根本特征不是国家所有制，而是联合起来的生产者所有制；不是国家替人民管理，而是人民自己管理；不是少数人代表多数人，而是多数人自己行使权力。</p><p>知道&quot;本来可以是别的样子&quot;，是想象&quot;未来可以是别的样子&quot;的前提。</p><p>恢复被篡改的定义，恢复被扼杀的可能性，这本身就是抵抗。</p><hr><blockquote><p>本文同步自知乎，<a href="https://zhuanlan.zhihu.com/p/2079496083537924613" target="_blank" rel="noreferrer">查看原文</a>（33 赞）</p></blockquote>',59)])])}const c=o(a,[["render",e]]);export{d as __pageData,c as default};
